double kwPerAmp = 480.0 * 1.732 * 0.85 / 1000.0;
double kw = (@Tag.Highland/Area100_RawWater/P101.MotorCurrent + @Tag.Highland/Area100_RawWater/P102.MotorCurrent) * kwPerAmp;
double dtHours = 1.0 / 3600.0;
@Tag.Highland/Plant/EnergyTotal = @Tag.Highland/Plant/EnergyTotal + kw * dtHours;
@Tag.Highland/Area100_RawWater/P101.Running = @Tag.Highland/Area100_RawWater/P101.MotorCurrent > 5.0 ? 1 : 0;
@Tag.Highland/Area100_RawWater/P102.Running = @Tag.Highland/Area100_RawWater/P102.MotorCurrent > 5.0 ? 1 : 0;
double vol = @Tag.Highland/Plant/TreatedVolumeTotal;
if (vol > 0.001) @Tag.Highland/KPI/SpecificEnergy = @Tag.Highland/Plant/EnergyTotal / vol;
